<?php
$pageTitle='Gerbang & Area';
$pageSubtitle='Kelola data gerbang IoT dan kapasitas area parkir.';
require_once __DIR__ . '/includes/header.php';
$action=$_POST['action']??$_GET['action']??'';
if($_SERVER['REQUEST_METHOD']==='POST'){
    if($action==='gate_create'){$pdo->prepare('INSERT INTO gates (kode_gate,nama_gate,lokasi,mode_gate,status) VALUES (?,?,?,?,?)')->execute([trim($_POST['kode_gate']),trim($_POST['nama_gate']),trim($_POST['lokasi']),$_POST['mode_gate'],(int)$_POST['status']]);flash('success','Gerbang berhasil ditambahkan.');}
    if($action==='area_create'){$pdo->prepare('INSERT INTO parking_areas (nama_area,kapasitas,lokasi,status) VALUES (?,?,?,?)')->execute([trim($_POST['nama_area']),(int)$_POST['kapasitas'],trim($_POST['lokasi']),(int)$_POST['status']]);flash('success','Area parkir berhasil ditambahkan.');}
    redirect('gates.php');
}
if($action==='delete_gate'){$pdo->prepare('DELETE FROM gates WHERE id_gate=?')->execute([(int)$_GET['id']]);flash('success','Gerbang dihapus.');redirect('gates.php');}
if($action==='delete_area'){$pdo->prepare('DELETE FROM parking_areas WHERE id_area=?')->execute([(int)$_GET['id']]);flash('success','Area dihapus.');redirect('gates.php');}
$gates=$pdo->query('SELECT * FROM gates ORDER BY id_gate DESC')->fetchAll();$areas=$pdo->query('SELECT * FROM parking_areas ORDER BY id_area DESC')->fetchAll();
?>
<div class="grid grid-2"><div class="card"><div class="card-title"><h3>Tambah Gerbang</h3></div><form method="post"><input type="hidden" name="action" value="gate_create"><div class="form-grid"><div class="form-group"><label>Kode Gerbang</label><input class="input" name="kode_gate" placeholder="GATE-03" required></div><div class="form-group"><label>Nama Gerbang</label><input class="input" name="nama_gate" required></div><div class="form-group"><label>Lokasi</label><input class="input" name="lokasi"></div><div class="form-group"><label>Mode</label><select class="select" name="mode_gate"><option>Masuk-Keluar</option><option>Masuk</option><option>Keluar</option></select></div><div class="form-group"><label>Status</label><select class="select" name="status"><option value="1">Aktif</option><option value="0">Nonaktif</option></select></div></div><div class="form-actions"><button class="btn btn-primary">Simpan Gerbang</button></div></form></div><div class="card"><div class="card-title"><h3>Tambah Area Parkir</h3></div><form method="post"><input type="hidden" name="action" value="area_create"><div class="form-grid"><div class="form-group"><label>Nama Area</label><input class="input" name="nama_area" required></div><div class="form-group"><label>Kapasitas</label><input class="input" type="number" name="kapasitas" min="0" required></div><div class="form-group"><label>Lokasi</label><input class="input" name="lokasi"></div><div class="form-group"><label>Status</label><select class="select" name="status"><option value="1">Aktif</option><option value="0">Nonaktif</option></select></div></div><div class="form-actions"><button class="btn btn-primary">Simpan Area</button></div></form></div></div>
<div class="grid grid-2" style="margin-top:18px"><div class="card"><div class="card-title"><h3>Daftar Gerbang</h3></div><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Nama</th><th>Mode</th><th>Terakhir Aktif</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($gates as $g): ?><tr><td><b><?= e($g['kode_gate']) ?></b></td><td><?= e($g['nama_gate']) ?><br><small><?= e($g['lokasi']) ?></small></td><td><?= e($g['mode_gate']) ?></td><td><?= e($g['last_seen']?:'-') ?></td><td><span class="badge <?= $g['status']?'badge-success':'badge-danger' ?>"><?= $g['status']?'Aktif':'Nonaktif' ?></span></td><td><a class="btn btn-danger btn-sm" data-confirm="Hapus gerbang?" href="gates.php?action=delete_gate&id=<?= $g['id_gate'] ?>">Hapus</a></td></tr><?php endforeach; ?></tbody></table></div></div><div class="card"><div class="card-title"><h3>Daftar Area</h3></div><div class="table-wrap"><table><thead><tr><th>Area</th><th>Kapasitas</th><th>Lokasi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($areas as $a): ?><tr><td><b><?= e($a['nama_area']) ?></b></td><td><?= (int)$a['kapasitas'] ?></td><td><?= e($a['lokasi']) ?></td><td><span class="badge <?= $a['status']?'badge-success':'badge-danger' ?>"><?= $a['status']?'Aktif':'Nonaktif' ?></span></td><td><a class="btn btn-danger btn-sm" data-confirm="Hapus area?" href="gates.php?action=delete_area&id=<?= $a['id_area'] ?>">Hapus</a></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<?php require_once __DIR__ . '/includes/footer.php'; ?>
